 if(input.type!="limit"||!positive(input.price)||!positive(text(detailRow,"price"))||decimal::compare(input.price,text(detailRow,"price"))==0)return fail(BrokerNotReady::RejectedBySafetyRule,"지정가 잔량 전부의 새 가격을 입력해 주세요.");
