 const auto rules=get(Operation::Rules,"stock-state"),quote=get(Operation::Quote,"krx-price"),depth=get(Operation::Depth,"krx-book"),reference=get(Operation::Reference,"minute-reference");if(!rules||!quote||!depth||!reference)return fail(BrokerNotReady::MissingEvidence,"종목 상태·현재가·호가·최근 분봉을 새로 확인해 주세요.");
